body:
{
  "pains": [
    {
      "id": "pain:paywall-creep",
      "statement": "Things I used to get for free keep moving behind the paywall, and the price goes up anyway.",
      "element": "b2c:functional:reduces_cost",
      "shape": {
        "surface": "A renewal notice or a locked feature they used last year: training log, weight and age-group leaderboards, matched runs, the Year in Sport recap.",
        "operational": "They open the subscription screen, add up which paid features they actually touched in the last month, and put Garmin Connect or intervals.icu next to it. Most of the audit comes out short.",
        "personal": "Years of loyalty stop feeling like loyalty and start feeling like being farmed. The word people reach for is 'pathetic', not 'expensive'."
      },
      "workflow": "The App Store or Google Play subscription screen the week the renewal email lands, with Garmin Connect open in the other tab to check what is free there.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "Renewal notice shows a materially higher price than last year", "cites": ["src:5"] },
        { "event": "Year in Sport recap goes subscriber-only after nine years of being free", "cites": ["src:6"] },
        { "event": "A feature they used weekly (training log, club and age-group leaderboards, matched runs) is switched to paid", "cites": ["src:7"] }
      ],
      "who_feels": ["economic_buyer", "end_user"],
      "by_role": {
        "economic_buyer": {
          "says": [
            { "situation": "venting", "verbatim": "mines going from £3.99 to £8.99, only a 125% increase!", "cites": ["src:5"] },
            { "situation": "when_refusing", "verbatim": "I will pay max $ 5 a month, but not $ 8 too much.", "cites": ["src:7"] },
            { "situation": "when_comparing", "verbatim": "it's been a nudge to get me to downgrade to the free version", "cites": ["src:5"] }
          ],
          "costs_them": "An annual line item they can no longer justify from use, plus the time spent re-auditing the app and testing a free alternative.",
          "fears": "Paying every year out of habit for a tier they would not choose again, and watching the next free feature disappear behind the same wall.",
          "dream_outcome": "A price they can defend out loud, and confidence that what is free today is still free next season."
        },
        "end_user": {
          "says": [
            { "situation": "venting", "verbatim": "How pathetic does an app need to be to put their 'Year In Review' behind a paywall when EVERYONE ELSE does theirs for free as a thanks for using their app?", "cites": ["src:6"] },
            { "situation": "when_it_bites", "verbatim": "particularly irritating is putting the training log behind a paywall which I use for looking at weekly mileages.", "cites": ["src:7"] },
            { "situation": "when_comparing", "verbatim": "The 'premium' version is losing its appeal slowly as more and more apps are requiring me to pay a monthly fee for their services", "cites": ["src:17"] }
          ],
          "costs_them": "A routine they built around a free feature, broken mid-season.",
          "fears": "That the free tier keeps thinning until the years of history they uploaded are effectively hostage.",
          "dream_outcome": "The stuff they generated themselves, their own log and their own year, stays theirs to look at."
        }
      },
      "segments": ["seg:casual", "seg:serious"],
      "feature_ref": null,
      "feature_note": "No feature in the product kills a pricing pain. What would kill it is a durable free floor: the training log and the personal year-in-review kept free, with paid limited to features that were never free.",
      "cites": ["src:5", "src:6", "src:7", "src:17"]
    },
    {
      "id": "pain:value-unclear",
      "statement": "I cannot work out what the subscription actually gives me that my watch app does not already give me for nothing.",
      "element": "b2c:functional:informs",
      "shape": {
        "surface": "A free trial that ends without them ever finding the feature that justifies it.",
        "operational": "They ask the forum instead of the product. The answers converge on two things, route builder and heatmaps, and both only matter when travelling somewhere unfamiliar.",
        "personal": "They feel like the mark rather than the athlete: paying for social, paying for a scoreboard, paying for something they cannot name."
      },
      "workflow": "A forum thread titled some version of 'is it worth it', posted the week the trial expires, answered by people listing route builder, heatmaps and live segments and nothing else.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "Free trial about to convert and they go looking for a reason to keep it", "cites": ["src:3"] },
        { "event": "Already own a Garmin and realise the analysis they care about is free in Garmin Connect", "cites": ["src:4"] },
        { "event": "A training-focused rider finds the deep analysis they wanted in a free tool instead", "cites": ["src:4"] }
      ],
      "who_feels": ["economic_buyer", "technical_evaluator", "end_user"],
      "by_role": {
        "economic_buyer": {
          "says": [
            { "situation": "when_comparing", "verbatim": "I found very little of use and nothing of 'must have' in the full version.", "cites": ["src:3"] },
            { "situation": "when_refusing", "verbatim": "Strava is purely social for me. I refuse to pay for social…", "cites": ["src:3"] },
            { "situation": "when_looking", "verbatim": "I've only found the subscription of value when I've traveled to unknown places & used their heat maps.", "cites": ["src:3"] }
          ],
          "costs_them": "Either a year of spend on a tier they cannot name a use for, or the hours spent migrating to something free.",
          "fears": "Being the person who pays for the thing everyone else uses free.",
          "dream_outcome": "One sentence they could say back that explains what the money buys, tied to something they do every week rather than twice a year on holiday."
        },
        "technical_evaluator": {
          "says": [
            { "situation": "when_comparing", "verbatim": "If you have a powermeter or train with power based training, skip both and use intervals.icu. It s free but it is worth donating to them.", "cites": ["src:4"] },
            { "situation": "when_comparing", "verbatim": "Both of the sets of features I just do not need currently...And Strava premium is only useful if you care about the segments.", "cites": ["src:4"] }
          ],
          "costs_them": "Running two platforms, one for the numbers and one for the people.",
          "fears": "Paying twice for one training picture split across two products.",
          "dream_outcome": "The analysis they trust and the people they train with in the same place, at one price."
        }
      },
      "segments": ["seg:casual", "seg:serious"],
      "feature_ref": "feat:plans",
      "cites": ["src:3", "src:4"]
    },
    {
      "id": "pain:leaderboard-integrity",
      "statement": "I lost a KOM to someone doing 112mph on a motorbike, and cleaning up the leaderboard is somehow my job.",
      "element": "b2c:emotional:rewards_me",
      "shape": {
        "surface": "A crown-lost email for a segment time no human on a bicycle set.",
        "operational": "They open the offending activity, check the speed trace, gather evidence, flag it, and then watch the rider relabel the ride as 'exercise' to dodge the flag. Repeat, weekly.",
        "personal": "The thing they train for stops meaning anything. Losing a KOM is supposed to sting because someone was faster, not because someone had an engine."
      },
      "workflow": "The crown-lost notification, then the activity page and its speed graph, then the flag dialog, then the same segment again a fortnight later.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "Crown-lost emails arriving constantly as motorbikes and e-bikes sweep local segments", "cites": ["src:13"] },
        { "event": "Flagged riders relabel the activity type to keep the time on the board", "cites": ["src:13"] },
        { "event": "A mass leaderboard reprocessing wipes out millions of efforts and people notice their own board change", "cites": ["src:20"] }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "venting", "verbatim": "I am getting emails constantly now [every time a KOM gets taken].", "cites": ["src:13"] },
            { "situation": "when_it_bites", "verbatim": "Motorcyclists seem to be regularly using Strava for road and off-road, with blatant speeding obvious to see.", "cites": ["src:13"] },
            { "situation": "when_it_bites", "verbatim": "After being flagged, lots are now changing to 'exercise' I guess to avoid them being pulled down.", "cites": ["src:13"] }
          ],
          "costs_them": "Unpaid moderation work on their own local segments, and a leaderboard they can no longer read as a ranking of riders.",
          "fears": "That the competition they organise their training around is just noise, and nobody is checking but them.",
          "dream_outcome": "Impossible efforts never reach the board in the first place, so a lost crown means someone was genuinely faster."
        }
      },
      "segments": ["seg:serious", "seg:casual"],
      "feature_ref": "feat:explore",
      "cites": ["src:13", "src:20"]
    },
    {
      "id": "pain:club-tracking-by-hand",
      "statement": "The club leaderboard wipes every Sunday night, so I keep the real standings in a spreadsheet I update by hand.",
      "element": "b2c:functional:organizes",
      "shape": {
        "surface": "A month-long club challenge whose scoreboard only exists for seven days at a time.",
        "operational": "Someone in the club copies members' totals into Google Sheets every evening, gives kudos to mark what they have already logged, and hand-adjusts for the activity types the club counts but Strava's club totals exclude, like hikes and walks. The technical ones give up and write a scraper.",
        "personal": "The organiser becomes the club's data entry clerk. The reward for volunteering is a nightly chore."
      },
      "workflow": "Every evening of the challenge: the club page on desktop (because the app leaderboard shows different columns), then Google Sheets, then back to give kudos as a done-marker.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "Club runs a month-long or year-long challenge and the weekly leaderboard resets under it", "cites": ["src:10", "src:17"] },
        { "event": "Club counts activity types that Strava's club totals exclude", "cites": ["src:11"] },
        { "event": "Organiser wants history or a members list beyond the weekly top 100 and finds there is none", "cites": ["src:12"] }
      ],
      "who_feels": ["champion", "end_user"],
      "by_role": {
        "champion": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "Mrs Dubs did one of these, people logged on Strava and she manually transferred into a spreadsheet giving Kudos when she'd logged it.", "cites": ["src:10"] },
            { "situation": "when_looking", "verbatim": "Yes - just trying to find something less manual. But that methodology seems as sound as anything", "cites": ["src:10"] },
            { "situation": "when_it_bites", "verbatim": "totals did not include all activity types (they exclude Hike, Walk etc.), and we wanted to count various activity types differently.", "cites": ["src:11"] }
          ],
          "costs_them": "Five to ten minutes a day of manual transcription for the length of the challenge, and sole ownership of a spreadsheet nobody else can take over.",
          "fears": "Getting a total wrong in a charity or club competition where people care about the result, and having no source of truth to check against.",
          "dream_outcome": "Set the challenge window, the activity types and the scoring once, and have the standings hold for the whole month without anyone touching a spreadsheet."
        },
        "end_user": {
          "says": [
            { "situation": "venting", "verbatim": "The 'inner crew competition' always gets fired up on Strava these days with people trying to be the top of our group, but at the end of the week, the stats reset with no real staying power", "cites": ["src:17"] }
          ],
          "costs_them": "The competition they were enjoying evaporates every Sunday.",
          "fears": "That the effort they put in over a month leaves no record anyone sees.",
          "dream_outcome": "A standing that accumulates over the season, not one that resets before it means anything."
        }
      },
      "segments": ["seg:clubs"],
      "feature_ref": null,
      "feature_note": "Clubs and challenges exist but do not kill this. What would: a club-owned challenge with an organiser-set window longer than a week, organiser-chosen activity types and scoring, persistent standings, and a full member list rather than a weekly top 100.",
      "cites": ["src:10", "src:11", "src:12", "src:17"]
    },
    {
      "id": "pain:club-duty-of-care",
      "statement": "Twenty people show up to my ride on the strength of a Strava event and all I have on any of them is a display name.",
      "element": "b2c:functional:reduces_risk",
      "shape": {
        "surface": "An RSVP list that tells the organiser who is coming and nothing about what to do if one of them goes down.",
        "operational": "Waivers are set once at club level and apply to every event under that banner, so a club whose events range from a coffee spin to a technical trail ride is covering both with the same paperwork. No emergency contact is collected anywhere in that flow, so the organiser ends up asking in a group chat or not at all.",
        "personal": "The volunteer who organised a social ride is quietly carrying the liability for it."
      },
      "workflow": "Creating the club event, then the RSVP list on the morning of the ride, then the group chat where they ask people to reply with a next-of-kin number.",
      "type": "latent",
      "confidence": "medium",
      "revealed_by": "feat:beacon",
      "triggers": [
        { "event": "Club runs events of genuinely different risk under one club-level waiver", "cites": ["src:18"] },
        { "event": "Organiser needs an emergency contact for a rider and finds the platform never asked for one", "cites": ["src:18"] },
        { "event": "Waiver text is updated and every member has to re-accept before their next RSVP", "cites": ["src:18"] }
      ],
      "who_feels": ["champion", "blocker"],
      "by_role": {
        "champion": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "Strava's waiver system does not collect emergency contacts.", "cites": ["src:18"] }
          ],
          "costs_them": "Chasing next-of-kin details by hand, and carrying personal exposure on a ride they volunteered to lead.",
          "fears": "Someone gets hurt on a club ride and the organiser has no way to reach their family and no paperwork that clearly covers that specific event.",
          "dream_outcome": "Per-event waivers and an emergency contact captured at RSVP, so turning up to the ride and being accounted for are the same action."
        },
        "blocker": {
          "says": [
            { "situation": "when_refusing", "verbatim": "Strava's waiver system does not collect emergency contacts.", "cites": ["src:18"] }
          ],
          "costs_them": "Nothing directly, which is the point: the club committee or insurer refuses the platform on paperwork grounds and the organiser goes elsewhere.",
          "fears": "An uninsured incident traced back to inadequate event-level consent.",
          "dream_outcome": "Documentation that satisfies an insurer without a lawyer being consulted per event."
        }
      },
      "segments": ["seg:clubs"],
      "feature_ref": null,
      "feature_note": "Beacon covers the solo athlete, not the group an organiser is responsible for. What would kill this: per-event waivers plus an emergency contact field captured at RSVP and visible to the organiser on the day.",
      "cites": ["src:18"]
    },
    {
      "id": "pain:run-for-the-feed",
      "statement": "Every run is public, so I end up running for the people watching instead of for me.",
      "element": "b2c:life_changing:motivation",
      "shape": {
        "surface": "Captions written as disclaimers, easy runs pushed too hard, activities quietly not posted.",
        "operational": "Before the run they think about the pace that will look right. During it they check the watch more than they need to. After it they annotate: 'with XX', so nobody reads the slow pace as theirs.",
        "personal": "The sport that was supposed to be the escape becomes another feed to perform for. Some people stop posting; some stop enjoying riding at all."
      },
      "workflow": "The caption box on the save-activity screen, and the watch face mid-run when they catch themselves checking pace for the audience rather than the effort.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "Running slower than usual with a friend and feeling the need to explain the pace publicly", "cites": ["src:9"] },
        { "event": "Chasing segment times they can never beat until the sport stops being fun", "cites": ["src:4"] },
        { "event": "Injury or a slow block, when the feed turns into a list of what everyone else is doing", "cites": ["src:19"] }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "venting", "verbatim": "I check my watch too often and I push myself every time.", "cites": ["src:9"] },
            { "situation": "when_it_bites", "verbatim": "When with slower friends, I'm embarrassed to admit that I always clarify in the caption on Strava: 'with XX'. A disclaimer, so no one mistakes the pace for my own.", "cites": ["src:9"] },
            { "situation": "when_refusing", "verbatim": "Strava premium nearly killed my love of cycling...I found myself chasing segments and stuff that I could never beat.", "cites": ["src:4"] },
            { "situation": "when_refusing", "verbatim": "I stopped posting my running to Strava and felt free, empowered to enjoy my runs and have improved as a result.", "cites": ["src:19"] }
          ],
          "costs_them": "Easy days run too hard, and eventually the account itself: people leave to get their sport back.",
          "fears": "Being judged on pace by people who do not know the context, and losing the enjoyment that got them into it.",
          "dream_outcome": "Log everything honestly, including the slow and the bad, without it being a performance."
        }
      },
      "segments": ["seg:casual", "seg:serious"],
      "feature_ref": null,
      "feature_note": "The social feed causes this rather than curing it. What would ease it: a default-private or friends-only mode that still counts toward clubs and challenges, so an unposted run is not an uncounted run.",
      "cites": ["src:4", "src:9", "src:19"]
    },
    {
      "id": "pain:lost-activity",
      "statement": "It stopped recording halfway through and the effort is just gone.",
      "element": "b2c:functional:quality",
      "shape": {
        "surface": "A walk or ride that ends short, or with a time that does not match the clock.",
        "operational": "They lose the segment matches for that ride, which means the PR and the leaderboard placing too. The fix people land on is to stop using the phone app and buy a dedicated GPS device.",
        "personal": "An hour of work with nothing to show. For anyone chasing a streak or a target, the missing entry is the injury."
      },
      "workflow": "The save screen at the end of the activity, then the segment list on the activity page where the matches they expected are not there.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "Recording stops mid-activity or logs the wrong elapsed time", "cites": ["src:1"] },
        { "event": "Scattered GPS trace means segments do not match and a dozen times are missing from one ride", "cites": ["src:14"] },
        { "event": "Repeat failures push the athlete to buy a separate device just to record reliably", "cites": ["src:14"] }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "venting", "verbatim": "The last few times that I have used it, it has either stopped before I have finished my walk, or recorded the wrong time.", "cites": ["src:1"] },
            { "situation": "when_it_bites", "verbatim": "I doubt it, used to have the same with an iPhone which is why I bought a Garmin", "cites": ["src:14"] },
            { "situation": "when_it_bites", "verbatim": "Another issue is a lot of segments on Strava are poorly set up", "cites": ["src:14"] }
          ],
          "costs_them": "The activity, the segment efforts inside it, and eventually a few hundred on hardware to work around the app.",
          "fears": "That the log they have built for years has holes in it they cannot fill.",
          "dream_outcome": "Press start, put the phone away, and trust that what they did is what gets saved."
        }
      },
      "segments": ["seg:casual", "seg:serious"],
      "feature_ref": "feat:track",
      "cites": ["src:1", "src:14"]
    },
    {
      "id": "pain:route-to-my-door",
      "statement": "Every run starts and ends at my house, and I never thought about what that tells a stranger.",
      "element": "b2c:functional:reduces_risk",
      "shape": {
        "surface": "Nothing. That is the problem: the exposure is only visible once a researcher or a news story points at it.",
        "operational": "Aggregated map data that is meant to be anonymous stops being anonymous where there are few users or few routes. Researchers describe it as a process of elimination, and the mitigation is buried in account settings the athlete has never opened.",
        "personal": "For anyone who has had a stalking scare, the app that logs their routine is the app that publishes it."
      },
      "workflow": "Account settings, the aggregated data usage toggle and the privacy zone radius, neither of which most athletes have ever visited.",
      "type": "latent",
      "confidence": "medium",
      "revealed_by": "feat:beacon",
      "triggers": [
        { "event": "Press or research coverage showing map data can be traced back to a home address", "cites": ["src:16"] },
        { "event": "Training somewhere with few other users, where elimination is trivial", "cites": ["src:16"] }
      ],
      "who_feels": ["end_user", "blocker"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "Strava users expect their personal information to be protected, and our work shows that this is not always the case", "cites": ["src:16"] },
            { "situation": "when_it_bites", "verbatim": "In areas where there are few users and/or few routes, it becomes a simple process of elimination", "cites": ["src:16"] }
          ],
          "costs_them": "Either the social features they joined for, or the peace of mind, because the safe setting is the one that hides them from everyone.",
          "fears": "That a habit logged for fitness becomes a schedule someone else can read.",
          "dream_outcome": "Share the run and the effort without shipping their front door and their Tuesday 7am with it."
        },
        "blocker": {
          "says": [
            { "situation": "when_refusing", "verbatim": "Users can go into their Strava account settings and opt out of contributing data to the 'aggregated data usage' feature", "cites": ["src:16"] }
          ],
          "costs_them": "Nothing, which is why it stays unresolved: the safety-minded partner or parent simply says do not use it.",
          "fears": "A real-world incident traced back to a public training pattern.",
          "dream_outcome": "Privacy that is the default rather than a setting the athlete has to know exists."
        }
      },
      "segments": ["seg:casual", "seg:serious"],
      "feature_ref": null,
      "feature_note": "Beacon is deliberate sharing with chosen contacts; it does not address unintended exposure through aggregate map data. What would: start and end obfuscation on by default, and aggregate contribution off by default.",
      "cites": ["src:16"]
    },
    {
      "id": "pain:feed-buries-friends",
      "statement": "The feed buries the people I actually ride with under stuff I did not ask to see.",
      "element": "b2c:functional:organizes",
      "shape": {
        "surface": "Older activities sitting above newer ones, club posts and promoted content mixed into the timeline.",
        "operational": "They scroll further to find the three people whose rides they care about, and give kudos to fewer of them as a result.",
        "personal": "The reason they stay on the platform is the people. Making the people harder to find is making the reason harder to feel."
      },
      "workflow": "The home feed, opened after a ride to see what their group did, scrolled past content they did not follow.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        { "event": "Feed switched from chronological to ranked", "cites": ["src:15"] },
        { "event": "Promoted and club content appearing between friends' activities", "cites": ["src:15"] }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "venting", "verbatim": "Losing the chronological order seems illogical to me too.", "cites": ["src:15"] },
            { "situation": "venting", "verbatim": "Why is that 'social' apps think non-chronological feeds are a good idea. It's shit with Instagram and it'll be shit here.", "cites": ["src:15"] },
            { "situation": "when_it_bites", "verbatim": "Do not like and then there will paid adverts in the feed", "cites": ["src:15"] }
          ],
          "costs_them": "Kudos given and received, which is the whole social loop.",
          "fears": "That the network turns into another algorithmic feed and stops being about the twenty people they actually train with.",
          "dream_outcome": "A feed they can set to plain reverse-chronological, limited to people they follow."
        }
      },
      "segments": ["seg:casual", "seg:serious", "seg:clubs"],
      "feature_ref": "feat:social",
      "cites": ["src:15"]
    },
    {
      "id": "pain:coach-cant-see-data",
      "statement": "My coach cannot see my data in the tool we actually coach in, because of Strava's API rules.",
      "element": "b2c:functional:integrates",
      "shape": {
        "surface": "A third-party app that used to show an athlete's activity to their coach and no longer can.",
        "operational": "The athlete rebuilds the pipe: sync the device to the analysis platform directly, keep Strava as the social layer only, and accept that the two pictures are separate.",
        "personal": "The athlete feels caught between a platform they pay for and a coaching relationship they pay for, over a policy neither of them chose."
      },
      "workflow": "The connected-apps screen and whatever coaching platform the relationship runs on, on the day an app announces it can no longer display shared data.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        { "event": "API terms change so third-party apps cannot show a user's data to anyone but that user", "cites": ["src:8"] },
        { "event": "A favourite connected app announces it is degrading or shutting down", "cites": ["src:8"] }
      ],
      "who_feels": ["end_user", "technical_evaluator"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "apps that do any sort of coaching on their platform are not allowed to show the end users data to their coach", "cites": ["src:8"] },
            { "situation": "when_refusing", "verbatim": "I have canceled my subscription today", "cites": ["src:8"] }
          ],
          "costs_them": "A working coaching setup, plus the migration to rebuild it around the device rather than around Strava.",
          "fears": "That every tool they have built their training around can be switched off by a terms update.",
          "dream_outcome": "Their own data flows to the people they choose, and the platform stays out of the middle of it."
        },
        "technical_evaluator": {
          "says": [
            { "situation": "when_comparing", "verbatim": "after this they will have much less incentive of improving their API, as it will be used less", "cites": ["src:8"] }
